export function nodeLabel(value,context,id){const node=byId(value.graph.nodes,id);if(!node)return '待选择步骤';const ids=sourceIds(context,value.business_name),index=ids.indexOf(node.source_step_id);return value.ui?.node_labels?.[id]||businessFor(context,value.business_name)?.steps?.[index]?.name||NODE_LABELS[node.kind]||'处理步骤';}
