export function setNode(value,id,patch){return updateGraphDraft(value,d=>{const n=byId(d.graph.nodes,id);if(!n)throw Error('原步骤已变化。');if(Object.entries(patch).some(([k,v])=>!same(n[k],v)))d.external_node_ids=[];Object.assign(n,clone(patch));});}
export function setRoleMember(value,role,id){return updateGraphDraft(value,d=>{if(d.role_bindings[role]!==id)d.external_node_ids=[];set(d.role_bindings,role,id);for(const node of d.graph.nodes)if(node.kind==='human'&&node.role===role)node.actor_id=id;});}
export function abilityPin(option,agentRole){return {capability_id:option.id,capability_hash:option.content_hash,agent_role:agentRole,input_bindings:{},arguments:{},input_schema:clone(option.input_schema),output_schema:clone(option.output_schema),adapter:option.adapter,release_version:option.release_version,max_attempts:option.max_attempts??option.budget?.max_attempts};}
export function selectAbility(value,nodeId,option){return updateGraphDraft(value,d=>{const node=byId(d.graph.nodes,nodeId);if(node?.kind!=='ability')throw Error('请选择能力步骤。');if(node.execution.capability_id){const old=d.ui.previous_executions?.[nodeId]||[];if(old.length>=10)throw Error('此节点已有10份原能力输入，请保留当前稿后另建修订，不能丢弃旧输入。');d.ui.previous_executions={...d.ui.previous_executions,[nodeId]:[...old,clone(node.execution)]};d.ui.previous_execution_number_tokens={...d.ui.previous_execution_number_tokens,[nodeId]:[...(d.ui.previous_execution_number_tokens?.[nodeId]||old.map(()=>({}))),graphWireNumericTokens(node.execution)]};const raw=Object.fromEntries(Object.entries(d.ui.number_texts||{}).filter(([key])=>Object.keys(node.execution.input_schema.properties||{}).some(field=>key==='ability:'+nodeId+':'+field||key.startsWith('ability:'+nodeId+':'+field+'/'))));d.ui.previous_number_texts={...d.ui.previous_number_texts,[nodeId]:[...(d.ui.previous_number_texts?.[nodeId]||old.map(()=>({}))),clone(raw)]};}for(const field of Object.keys(node.execution.input_schema?.properties||{}))clearNumberTexts(d,'ability:'+nodeId+':'+field);node.execution=abilityPin(option,node.execution.agent_role);d.external_node_ids=d.external_node_ids.filter(id=>id!==nodeId);delete d.node_actions[nodeId];});}
