export function addGraphInput(value,label,kind='string'){return updateGraphDraft(value,d=>{if(!nonempty(label))throw Error('请填写业务输入名称。');const key=nextId(Object.keys(d.graph.input_schema.properties),'input_');set(d.graph.input_schema.properties,key,{...fieldSchema(kind),title:label});d.ui.input_labels[key]=label;});}
export function addWaitEntityInput(value,subscriptionId,label){let next=updateGraphDraft(value,d=>{if(!d.graph.subscriptions.some(s=>s.id===subscriptionId)||!nonempty(label))throw Error('请核对实际等待安排和关联对象名称。');const field=nextId(Object.keys(d.graph.input_schema.properties),'input_');set(d.graph.input_schema.properties,field,{type:'string',title:label,description:'发起任务时，从本次选定对象中明确选择一个关联对象。'});d.graph.input_schema.required.push(field);d.ui.input_labels[field]=label;});const field=Object.keys(next.graph.input_schema.properties).find(key=>!own(value.graph.input_schema.properties,key)),added=addReference(next,{source:'input',field,spec:next.graph.input_schema.properties[field]});next=added.value;byId(next.graph.subscriptions,subscriptionId).correlation_ref=added.key;return next;}
export function fieldSchema(kind='string',nullable=false){const base=kind==='date'?{type:'string',format:'date'}:kind==='object'?schema():kind==='array'?{type:'array',items:{type:'string'},maxItems:100}:{type:kind};if(nullable)base.type=[base.type,'null'];return base;}
export function addOutputField(value,nodeId,label,kind='string'){return updateGraphDraft(value,d=>{const node=byId(d.graph.nodes,nodeId);if(node?.kind!=='human'||!nonempty(label))throw Error('请为人工填写项命名。');const key=nextId(Object.keys(node.output_schema.properties),'answer_');set(node.output_schema.properties,key,{...fieldSchema(kind),title:label});node.output_schema.required.push(key);});}
export function addControl(value,kind){return updateGraphDraft(value,d=>{if(!['decision','fork','wait','end'].includes(kind))throw Error('此控制结构不能单独添加。');const id=nextId(d.graph.nodes,kind+'_'),node={id,kind,source_step_id:null,guards:guards()};if(kind==='decision')node.predicate_id='';if(kind==='wait'){const subscription=nextId(d.graph.subscriptions,'subscription_');Object.assign(node,{subscription_id:subscription,timeout_seconds:null});d.graph.subscriptions.push({id:subscription,event_type:'',correlation_ref:'',output_schema:schema()});}if(kind==='fork'){const joinId=nextId(d.graph.nodes,'join_');Object.assign(node,{join_id:joinId,branch_ids:['branch_1','branch_2']});d.graph.nodes.push({id:joinId,kind:'join',source_step_id:null,guards:guards(),fork_id:id,policy:'all'});}d.graph.nodes.push(node);d.ui.selected_node_id=id;});}
export function removeControl(value,id){return updateGraphDraft(value,d=>{const node=byId(d.graph.nodes,id);if(!node||node.source_step_id!==null||node.kind==='join')throw Error('原业务步骤必须保留；汇合随其并行结构一起删除。');const remove=new Set([id,...(node.kind==='fork'?[node.join_id]:[])]);if(d.graph.edges.some(e=>remove.has(e.from)||remove.has(e.to)))throw Error('请先逐条核对并移除该结构的连线，原对应关系仍保留。');d.graph.nodes=d.graph.nodes.filter(n=>!remove.has(n.id));if(node.kind==='wait'){d.graph.subscriptions=d.graph.subscriptions.filter(s=>s.id!==node.subscription_id);if(d.event_source_fragments)delete d.event_source_fragments[node.subscription_id];clearNumberTexts(d,'wait:'+id);}if(remove.has(d.graph.entry))d.graph.entry='';});}
export function connectNodes(value,from,to,on='success',branch_id=null){return updateGraphDraft(value,d=>{if(!byId(d.graph.nodes,from)||!byId(d.graph.nodes,to))throw Error('请选择真实的起点和去向。');if(d.graph.edges.some(e=>e.from===from&&e.on===on&&e.branch_id===branch_id))throw Error('此出口已有连线，请编辑原连线。');d.graph.edges.push({id:nextId(d.graph.edges,'edge_'),from,to,on,branch_id,loop_id:null});});}
export function removeEdge(value,id){return updateGraphDraft(value,d=>{const edge=byId(d.graph.edges,id);if(edge?.loop_id)throw Error('请先移除此连线的重复次数约束。');d.graph.edges=d.graph.edges.filter(e=>e.id!==id);});}
export function addPredicate(value,label){return updateGraphDraft(value,d=>{const id=nextId(d.graph.predicates,'condition_');set(d.graph.predicates,id,{op:'ref',key:''});d.ui.predicate_labels[id]=nonempty(label)?label:'待明确条件';});}
