export function addGoal(value,label){return updateGraphDraft(value,d=>{const id=nextId(d.graph.goals,'goal_');d.graph.goals.push({id,required_nodes:[]});d.ui.goal_labels[id]=nonempty(label)?label:'待明确的完成标准';});}
