export function setLoop(value,edgeId,maximum){return updateGraphDraft(value,d=>{const edge=byId(d.graph.edges,edgeId);if(!edge)throw Error('请选择明确的返回连线。');if(maximum===null){clearNumberTexts(d,'loop:'+edgeId);d.graph.loops=d.graph.loops.filter(l=>l.id!==edge.loop_id);edge.loop_id=null;return;}if(!Number.isInteger(maximum)||maximum<1||maximum>100)throw Error('最多重复次数须为1至100次。');let loop=byId(d.graph.loops,edge.loop_id);if(!loop){loop={id:nextId(d.graph.loops,'repeat_'),edge_id:edgeId,max_iterations:maximum};d.graph.loops.push(loop);edge.loop_id=loop.id;}else loop.max_iterations=maximum;});}
export function schemaTargets(context){const targets=[];for(const [kind,items] of [['object',context?.schema_origins?.objects||[]],['relationship',context?.schema_origins?.relationships||[]]])for(const item of items){targets.push({label:item.name,ref:{kind:'schema_origin',id:item.name,field:null,field_type:null,origin:clone(item.origin)}});if(kind==='object')for(const field of item.definition?.fields||[])targets.push({label:item.name+' · '+field.label,ref:{kind:'schema_origin',id:item.name,field:field.label,field_type:field.kind,origin:clone(item.origin)}});}return targets;}
export function targetOptions(value,context){const options=[];for(const node of value.graph.nodes){const label=nodeLabel(value,context,node.id);options.push({label,ref:{kind:'node',id:node.id}});if(['fork','join','wait'].includes(node.kind))options.push({label:NODE_LABELS[node.kind]+'：'+label,ref:{kind:node.kind,id:node.id}});}for(const edge of value.graph.edges)options.push({label:nodeLabel(value,context,edge.from)+' → '+nodeLabel(value,context,edge.to)+(edge.on==='true'?'（成立）':edge.on==='false'?'（不成立）':edge.on==='timeout'?'（到期）':edge.on==='branch'?'（并行分支）':''),ref:{kind:'edge',id:edge.id}});for(const id of Object.keys(value.graph.predicates))options.push({label:'判断：'+(value.ui?.predicate_labels?.[id]||'已采用条件'),ref:{kind:'predicate',id}});for(const id of Object.keys(value.graph.references))options.push({label:'输入或保存值：'+referenceLabel(value,context,id),ref:{kind:'value_ref',id}});for(const goal of value.graph.goals)options.push({label:'完成标准：'+(value.ui?.goal_labels?.[goal.id]||'已采用完成标准'),ref:{kind:'goal',id:goal.id}});for(const role of Object.keys(value.role_bindings))options.push({label:'实际职责：'+role,ref:{kind:'role_binding',id:role}});for(const subscription of value.graph.subscriptions)options.push({label:'等待接收：'+(subscription.event_type||'尚未明确的事件'),ref:{kind:'subscription',id:subscription.id}});return [...options,...schemaTargets(context).map(item=>({...item,label:'已采用结构：'+item.label}))];}
export function allowedTargetKinds(owner,field){const k=owner.kind;if(['object','business_identity','platform_identity_confirmation'].includes(k))return ['schema_origin'];if(k==='field')return ['schema_origin','value_ref'];if(k==='relationship')return ['schema_origin'];if(k==='business')return field==='output'?['goal']:['predicate','subscription','node'];if(k==='step')return ['next_index','else_index'].includes(field)?['edge']:field==='branch_condition'?['predicate']:['node','role_binding'];if(k==='participant')return field==='agent'?['role_binding']:['node','goal','role_binding','subscription'];if(k==='condition')return field==='step_indices'?['node']:['predicate'];if(k==='interaction')return ['from_participant_index','to_participant_index'].includes(field)?['role_binding']:field==='step_indices'?['node']:field==='condition'?['predicate']:['edge','wait','subscription'];if(k==='coordination')return field==='step_indices'?['node']:field==='start_rule'?['predicate']:field==='wait_rule'?['wait','join','edge']:field==='join_rule'?['join','edge','goal']:['fork','edge','node'];return ['predicate','goal','schema_origin','role_binding','node','wait','value_ref'];}
